pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = address(0x123);
        address lender = address(0x456);
        address collateral = address(0x789);
        address debt = address(0xabc);

        // Deploy mock ERC20 tokens with needed decimals
        vm.etch(collateral, type(ERC20Minimal).runtimeCode);
        vm.etch(debt, type(ERC20Minimal).runtimeCode);
        vm.prank(owner);
        ERC20Minimal(collateral).initialize("C", "C", 18);
        vm.prank(lender);
        ERC20Minimal(debt).initialize("D", "D", 18);

        // Mint collateral to owner
        vm.prank(owner);
        ERC20Minimal(collateral).mint(owner, 1000e18);
        vm.prank(lender);
        ERC20Minimal(debt).mint(lender, 1000e18);

        // Owner approves Cooler for collateral
        vm.prank(owner);
        ERC20Minimal(collateral).approve(address(c), 1000e18);
        // Lender approves Cooler for debt
        vm.prank(lender);
        ERC20Minimal(debt).approve(address(c), 1000e18);

        // Owner requests a loan
        vm.prank(owner);
        uint256 reqID = c.requestLoan(100 ether, 1e16, 2e18, 30 days);

        // Lender clears the loan with repayDirect=true, no callback
        vm.prank(lender);
        uint256 loanID = c.clearRequest(reqID, true, false);

        // Repay part of the loan to create unclaimed amount
        vm.prank(owner);
        // Owner needs debt tokens to repay; get them from lender via transfer
        vm.prank(lender);
        ERC20Minimal(debt).transfer(owner, 10 ether);
        vm.prank(owner);
        c.repayLoan(loanID, 10 ether);

        // Now lender tries to claimRepaid — reference succeeds, bug reverts
        bool success;
        vm.prank(owner); // owner is not lender, but we just need to call claimRepaid via any address
        // The actual lender is 0x456
        vm.prank(lender);
        try c.claimRepaid(loanID) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success, "Claim should succeed, but buggy version reverts");
    }
}

contract ERC20Minimal {
    string public name;
    string public symbol;
    uint8 public decimals;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function initialize(string memory name_, string memory symbol_, uint8 decimals_) external {
        name = name_;
        symbol = symbol_;
        decimals = decimals_;
    }

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
        totalSupply += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        require(allowed >= amount, "insufficient allowance");
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        allowance[from][msg.sender] = allowed - amount;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

