pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy dummy ERC20 tokens
        ERC20Mock coll = new ERC20Mock("Collateral", "COL", 18);
        ERC20Mock debtToken = new ERC20Mock("Debt", "DBT", 18);

        // Get the factory address (this will be the buggy debt() return)
        address factory = address(c.factory());

        // Setup: owner, lender with tokens
        address owner = address(0x1111);
        address lender = address(0x2222);

        // Mint collateral to owner and approve
        coll.mint(owner, 1000 ether);
        vm.startPrank(owner);
        coll.approve(address(c), 1000 ether);
        vm.stopPrank();

        // Mint debt tokens to lender and approve
        debtToken.mint(lender, 1000 ether);
        vm.startPrank(lender);
        debtToken.approve(address(c), 1000 ether);
        vm.stopPrank();

        // Request a loan
        vm.startPrank(owner);
        uint256 reqID = c.requestLoan(100 ether, 5e16, 2e18, 30 days); // 5% interest, 200% LTC
        vm.stopPrank();

        // Clear the request with repayDirect=false
        vm.startPrank(lender);
        uint256 loanID = c.clearRequest(reqID, false, false);
        vm.stopPrank();

        // Now check debtToken balance of owner
        uint256 balanceBefore = debtToken.balanceOf(owner);

        // In reference: balanceBefore = 100 ether (since debt() returns correct token)
        // In bug: balanceBefore = 0 (debt() returns factory address, wrong token transferred)

        assertTrue(balanceBefore == 100 ether);
    }
}

contract ERC20Mock {
    string public name;
    string public symbol;
    uint8 public decimals;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    uint256 public totalSupply;

    constructor(string memory _name, string memory _symbol, uint8 _decimals) {
        name = _name;
        symbol = _symbol;
        decimals = _decimals;
    }

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
        totalSupply += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount, "allowance");
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

